import java.util.*;

class Solution {
  public List<String> generateAbbreviations(String word) {
    List<String> res = new ArrayList<>();
    build(word, 0, new StringBuilder(), 0, res);
    return res;
  }

  // count: letters abbreviated so far but not yet written
  private void build(String w, int i, StringBuilder sb, int count, List<String> res) {
    int len = sb.length();
    if (i == w.length()) {
      if (count > 0) sb.append(count);
      res.add(sb.toString());
    } else {
      build(w, i + 1, sb, count + 1, res);
      if (count > 0) sb.append(count);
      sb.append(w.charAt(i));
      build(w, i + 1, sb, 0, res);
    }
    sb.setLength(len);
  }
}
